CREATE TRIGGER mobile_oidc_exemption_au AFTER UPDATE ON user_login_mfa_exemptions FOR EACH ROW BEGIN IF (SELECT observer_enabled FROM mobile_oidc_control WHERE singleton_id=1)=1 AND (TRUE) THEN INSERT INTO mobile_oidc_identity_epoch(u_id,generation) VALUES(NEW.u_id,HEX(RANDOM_BYTES(24))) ON DUPLICATE KEY UPDATE security_version=security_version+1; IF OLD.u_id<>NEW.u_id THEN INSERT INTO mobile_oidc_identity_epoch(u_id,generation) VALUES(OLD.u_id,HEX(RANDOM_BYTES(24))) ON DUPLICATE KEY UPDATE security_version=security_version+1; END IF; END IF; END$$
CREATE TRIGGER mobile_oidc_exemption_ad AFTER DELETE ON user_login_mfa_exemptions FOR EACH ROW BEGIN IF (SELECT observer_enabled FROM mobile_oidc_control WHERE singleton_id=1)=1 AND (TRUE) THEN INSERT INTO mobile_oidc_identity_epoch(u_id,generation) VALUES(OLD.u_id,HEX(RANDOM_BYTES(24))) ON DUPLICATE KEY UPDATE security_version=security_version+1; END IF; END$$
