CREATE TRIGGER mobile_oidc_pilot_ad AFTER DELETE ON user_login_mfa_pilot_users FOR EACH ROW BEGIN IF (SELECT observer_enabled FROM mobile_oidc_control WHERE singleton_id=1)=1 AND (TRUE) THEN INSERT INTO mobile_oidc_identity_epoch(u_id,generation) VALUES(OLD.u_id,HEX(RANDOM_BYTES(24))) ON DUPLICATE KEY UPDATE security_version=security_version+1; END IF; END$$
CREATE TRIGGER mobile_oidc_policy_ai AFTER INSERT ON user_login_mfa_policy FOR EACH ROW BEGIN IF (SELECT observer_enabled FROM mobile_oidc_control WHERE singleton_id=1)=1 THEN UPDATE mobile_oidc_control SET policy_epoch=policy_epoch+1 WHERE singleton_id=1; END IF; END$$
CREATE TRIGGER mobile_oidc_policy_au AFTER UPDATE ON user_login_mfa_policy FOR EACH ROW BEGIN IF (SELECT observer_enabled FROM mobile_oidc_control WHERE singleton_id=1)=1 THEN UPDATE mobile_oidc_control SET policy_epoch=policy_epoch+1 WHERE singleton_id=1; END IF; END$$
